#include <stdio.h>
#include <string.h>

int countOccurrences(const char *str, char target) {
    int count = 0;
    while (*str) {
        if (*str == target) count++;
        str++;
    }
    return count;
}

int main() {
    char str[1000];
    char target;
    if (scanf("%s %c", str, &target) == 2) {
        printf("%d", countOccurrences(str, target));
    }
    return 0;
}

